Lemma bt_and3 : forall c (w k : Z) (t : bool), 0 <= w + k ->
  match c with BC_EQ => ((w + k) mod 4 =? 0) = t | BC_NE => negb ((w + k) mod 4 =? 0) = t | _ => False end ->
